			h_register_shadow <= 0;
		end else if (!check) begin
			if (rvfi_valid && !rvfi_trap && rvfi_order < checker_inst.insn_order &&
					(rvfi_rd_addr == checker_inst.register_index)) begin
				h_register_shadow <= rvfi_rd_wdata;
				h_register_written <= 1;
			end
		end
	end

	always @(posedge clock) begin
		if (!reset) begin
			h_shadow_written_match: assert(checker_inst.register_written == h_register_written);
			h_shadow_value_match: assert(checker_inst.register_shadow == h_register_shadow);
		end
	end

	// Architectural value model for the checker-selected register index, driven by the RVFI stream.
	reg h_arch_written;
	reg [`RISCV_FORMAL_XLEN-1:0] h_arch_value;

	always @(posedge clock) begin
		if (reset) begin
			h_arch_written <= 0;
			h_arch_value <= 0;
		end else begin
			if (checker_inst.register_index == 0) begin
				h_arch_written <= 1;
				h_arch_value <= 0;
