			if (rvfi_valid && !rvfi_trap && h_arch_written && (rvfi_rs2_addr == checker_inst.register_index)) begin
				h_rvfi_rs2_matches_model: assert(rvfi_rs2_rdata == h_arch_value);
			end
		end
	end

/// Helper Assertion End
endmodule

